		async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
			if (!config.enabled) {
				return { content: [{ type: "text", text: `pi-memory disabled${config.disabledReason ? ` (${config.disabledReason})` : ""}` }], details: { disabled: true } };
			}
			if (isMemorySubAgentCtx(ctx)) {
				return { content: [{ type: "text", text: "Memory note skipped: running inside a memory sub-agent." }], details: { subagent: true } };
			}
			const text = params.text.trim();
			if (!text) throw new Error("memory_note text cannot be empty");
			const cwd = ctx?.cwd ?? process.cwd();
			const noteSlug = await resolveProjectSlug(cwd);
			const noteSessionId = ctx?.sessionManager?.getSessionId?.() ?? (originSessionId || "manual-note");
			const path = appendManualInboxNote({ text, slug: noteSlug, sessionId: noteSessionId });
			try {
				const db = memoryDb ?? openMemoryDb();
				db.insertSession({ id: noteSessionId, cwd, projectSlug: noteSlug, source: (ctx as { source?: string } | undefined)?.source });
				db.insertObservation({ sessionId: noteSessionId, kind: "manual_note", projectSlug: noteSlug, content: text, metadata: { source: "tool", inboxPath: path } });
