describe("sqlite connection pragmas (SQLITE_BUSY regression)", () => {
	test("sets a non-zero busy_timeout so concurrent writers wait instead of throwing", () => {
		// Regression: a workflow fan-out spawns several sessions, each with its
		// own connection to the same memory.sqlite. Under WAL writers serialize,
		// so without a per-connection busy_timeout a concurrent insertObservation
		// throws SQLITE_BUSY immediately. busy_timeout makes it wait its turn.
