async function openDialog(pi: ExtensionAPI, ctx: ExtensionContext): Promise<void> {
	if (!ctx.hasUI) {
		ctx.ui.notify("Monitors require interactive mode", "error");
		return;
	}
	const { Container, SelectList, Text } = await loadMonitorUi();
	const all = [...monitors.values()].sort((a, b) => {
		const ar = a.status === "running" ? 0 : 1;
		const br = b.status === "running" ? 0 : 1;
		if (ar !== br) return ar - br;
		return b.startedAt - a.startedAt;
	});
	if (all.length === 0) {
		ctx.ui.notify("No monitors", "info");
		return;
	}

	const items: SelectItem[] = all.map((m) => ({
		value: m.id,
		label: `${statusGlyph(m.status)} ${m.description}`,
		description: `${m.status} · ${m.totalLines} line${m.totalLines !== 1 ? "s" : ""} · ${m.command.slice(0, 80)}`,
	}));

