244	class PlanningTasksPane implements ExtensionMainPaneComponent {
245		private selected = 0;
246		private detail: string | undefined;
247	
248		constructor(
249			private readonly tui: { requestRender(): void },
250			private readonly theme: ExtensionContext["ui"]["theme"],
251			private readonly requestHide: () => void,
252		) {}
253	
254		onEscape(): boolean {
255			this.requestHide();
256			return true;
257		}
258	
259		invalidate(): void {}
260	
261		handleInput(data: string): void {
262			const tasks = openPlanningTasks();
263			if (data === "\u001b[A") {
264				this.selected = Math.max(0, this.selected - 1);
265				this.detail = undefined;
266				this.tui.requestRender();
267				return;
268			}
269			if (data === "\u001b[B") {
270				this.selected = Math.min(Math.max(0, tasks.length - 1), this.selected + 1);
271				this.detail = undefined;
272				this.tui.requestRender();
273				return;
274			}
275			if (data === "\r" || data === "\n") {
276				const task = tasks[this.selected];
277				this.detail = task ? formatTaskDetail(task) : "No planning task selected.";
278				this.tui.requestRender();
279				return;
280			}
281			if (data === "\u001b") this.requestHide();
282		}
