321	function renderPlanningTaskLine(
322		task: PlanningTask,
323		fg: (key: string, text: string) => string,
324		bold: (text: string) => string,
325	): string {
326		const label = task.status === "in_progress" && task.activeForm ? task.activeForm : task.subject;
327		const icon = task.status === "in_progress" ? "◐" : "☐";
328		const base = task.status === "in_progress" ? fg("accent", bold(`${icon} ${task.id} ${label}`)) : fg("muted", `${icon} ${task.id} ${label}`);
329		const owner = task.owner ? ` owner=${task.owner}` : "";
330		const blockedBy = task.blockedBy.length > 0 ? ` blocked_by=${task.blockedBy.join(",")}` : "";
331		const metadata = task.metadata && Object.keys(task.metadata).length > 0 ? ` metadata=${JSON.stringify(task.metadata)}` : "";
332		return `${base}${fg("dim", `${owner}${blockedBy}${metadata}`)}`;
333	}
334	
335	function recordTaskSnapshot(pi: Pick<ExtensionAPI, "appendEntry">, store: TaskStore): Effect.Effect<void> {
336		return Effect.sync(() => {
337			pi.appendEntry("task-tools", taskSnapshotEvent(store));
338		});
339	}
340	
341	function recordIfPossible(pi: Pick<ExtensionAPI, "appendEntry"> | undefined, store: TaskStore): void {
342		if (!pi) return;
343		Effect.runSync(recordTaskSnapshot(pi, store));
344	}
345	
346	function taskResult<TDetails>(text: string, details: TDetails): AgentToolResult<TDetails> {
347		return { content: [{ type: "text", text }], details };
348	}
349	
350	function taskError(error: unknown): AgentToolResult<{ error: string }> {
351		return {
352			content: [{ type: "text", text: error instanceof Error ? error.message : String(error) }],
353			details: { error: error instanceof Error ? error.message : String(error) },
354			isError: true,
355		} as AgentToolResult<{ error: string }> & { isError: boolean };
356	}
357	
358	function formatTaskList(tasks: PlanningTask[], all: PlanningTask[]): string {
359		if (all.length === 0) return "No tasks.";
360		const done = all.filter((task) => task.status === "completed").length;
361		const inProgress = all.filter((task) => task.status === "in_progress").length;
362		const open = all.length - done - inProgress;
363		const header = `${all.length} tasks (${done} done, ${inProgress} in progress, ${open} open)`;
364		const openIds = new Set(all.filter((task) => task.status !== "completed").map((task) => task.id));
365		return [header, ...tasks.map((task) => formatTask(task, openIds))].join("\n");
366	}
367	
368	function formatTask(task: PlanningTask, openIds?: Set<string>): string {
369		const label = task.status === "in_progress" && task.activeForm ? task.activeForm : task.subject;
370		const owner = task.owner ? ` owner=${task.owner}` : "";
371		const blockers = openIds ? task.blockedBy.filter((id) => openIds.has(id)) : task.blockedBy;
372		const blockedBy = blockers.length > 0 ? ` blocked_by=${blockers.join(",")}` : "";
373		const blocks = task.blocks.length > 0 ? ` blocks=${task.blocks.join(",")}` : "";
374		return `${task.id} [${task.status}] ${label}${owner}${blockedBy}${blocks}`;
375	}
376	
377	function formatTaskDetail(task: PlanningTask): string {
378		const lines = [
379			`${task.id} [${task.status}] ${task.subject}`,
380			`created: ${new Date(task.createdAt).toISOString()}`,
381			`updated: ${new Date(task.updatedAt).toISOString()}`,
382		];
383		if (task.activeForm) lines.push(`active: ${task.activeForm}`);
384		if (task.description) lines.push(`description: ${task.description}`);
385		if (task.owner) lines.push(`owner: ${task.owner}`);
386		if (task.blockedBy.length > 0) lines.push(`blocked by: ${task.blockedBy.join(", ")}`);
387		if (task.blocks.length > 0) lines.push(`blocks: ${task.blocks.join(", ")}`);
388		if (task.metadata && Object.keys(task.metadata).length > 0) lines.push(`metadata: ${JSON.stringify(task.metadata)}`);
389		return lines.join("\n");
390	}
