assert.equal(fromString.details.task.description, "string body line");

const fromJsonString = await call("task_create", { task: JSON.stringify({ title: "Title alias", body: "Body alias" }) });
assert.equal(fromJsonString.details.task.subject, "Title alias");
assert.equal(fromJsonString.details.task.description, "Body alias");

const withActive = await call("TaskCreate", { subject: "Design schema", activeForm: "Designing schema" });
assert.equal(withActive.details.task.activeForm, "Designing schema");
const activeId = withActive.details.task.id;
await call("TaskUpdate", { taskId: activeId, status: "in_progress" });
assert(widgets.at(-1).value.some((line) => line.includes(`◐ #${activeId.replace("task-", "")} Designing schema`)), "in-progress widget line uses activeForm as active verb");
const activeList = await call("TaskList", {});
assert.match(activeList.content[0].text, new RegExp(`#${activeId.replace("task-", "")} \\[in_progress\\] Design schema`), "TaskList summary keeps subject while widget uses activeForm");

const depA = (await call("TaskCreate", { subject: "Dep A" })).details.task.id;
const depB = (await call("TaskCreate", { subject: "Dep B" })).details.task.id;
const consumer = (await call("TaskCreate", { subject: "Consumer" })).details.task.id;
const added = await call("TaskUpdate", { taskId: consumer, addBlockedBy: [depA, depB] });
assert.deepEqual(added.details.task.blockedBy, [depA, depB]);
await call("TaskUpdate", { task_id: depA, addBlocks: [consumer] });
assert.deepEqual((await call("TaskGet", { taskId: consumer })).details.task.blockedBy, [depA, depB]);
const cycle = await call("TaskUpdate", { taskId: depA, addBlockedBy: [consumer] });
assert.equal(cycle.isError, true, "dependency cycles are rejected");
assert.match(cycle.content[0].text, /Task dependency cycle/);

const withMeta = await call("TaskCreate", { subject: "Meta task", metadata: { a: 1, b: 2 } });
const metaId = withMeta.details.task.id;
assert.deepEqual(withMeta.details.task.metadata, { a: 1, b: 2 });
const mergedMeta = await call("TaskUpdate", { taskId: metaId, metadata: { a: 9, b: null } });
assert.deepEqual(mergedMeta.details.task.metadata, { a: 9 });

const blocker = (await call("TaskCreate", { subject: "Blocker" })).details.task.id;
const waiter = (await call("TaskCreate", { subject: "Waiter", blockedBy: [blocker] })).details.task.id;
await call("TaskUpdate", { taskId: blocker, status: "completed" });
const stillBlocking = (await call("TaskCreate", { subject: "Still blocking" })).details.task.id;
const actuallyBlocked = (await call("TaskCreate", { subject: "Actually blocked", blockedBy: [stillBlocking] })).details.task.id;
const filtered = await call("TaskList", {});
const filteredLines = filtered.content[0].text.split("\n");
const waiterLine = filteredLines.find((line) => line.startsWith(`#${waiter.replace("task-", "")} `));
assert(waiterLine && !waiterLine.includes("blocked by"), "completed blockers hidden in list output");
assert(filteredLines.findIndex((line) => line.startsWith(`#${waiter.replace("task-", "")} `)) < filteredLines.findIndex((line) => line.startsWith(`#${actuallyBlocked.replace("task-", "")} `)), "tasks with only completed blockers sort as ready");
assert.deepEqual((await call("TaskGet", { taskId: waiter })).details.task.blockedBy, [blocker]);

const doomed = (await call("TaskCreate", { subject: "Doomed" })).details.task.id;
const dependent = (await call("TaskCreate", { subject: "Dependent", blockedBy: [doomed] })).details.task.id;
const deleted = await call("TaskUpdate", { taskId: doomed, status: "deleted" });
assert.match(deleted.content[0].text, /^Deleted task #/);
assert(!(await call("TaskList", {})).content[0].text.includes(`#${doomed.replace("task-", "")} `), "deleted task gone from list");
assert.deepEqual((await call("TaskGet", { taskId: dependent })).details.task.blockedBy, [], "deleted task scrubbed from blocker lists");
assert.equal((await call("TaskGet", { taskId: doomed })).details.task, null);

const resumedTools = {};
const resumedHandlers = {};
factory({ ...api, registerTool: (tool) => (resumedTools[tool.name] = tool), on: (event, handler) => (resumedHandlers[event] = handler) });
resumedHandlers.session_start({ type: "session_start", reason: "resume" }, ctx);
const resumedMissing = await resumedTools.TaskGet.execute("call", { taskId: doomed }, undefined, undefined, ctx);
assert.equal(resumedMissing.details.task, null, "deleted task stays deleted after resume");

for (const task of mod.planningTaskStoreSnapshot().tasks.filter((task) => task.status !== "completed")) {
	await call("TaskUpdate", { taskId: task.id, status: "completed" });
}
assert.deepEqual(widgets.at(-1), { key: "planning-tasks", value: undefined, options: { placement: "aboveEditor" } }, "all-complete clears task checklist widget");

// ── Append-only task reminder (CC heartbeat parity) ─────────────────────────
// All tasks are completed at this point, so openTasks() is empty.
assert.equal(typeof handlers.turn_start, "function", "turn_start handler registered");
assert.equal(typeof handlers.context, "function", "context handler registered");

const baseMessages = [
	{ role: "user", content: [{ type: "text", text: "first prompt" }], timestamp: 1 },
	{ role: "assistant", content: [{ type: "text", text: "ok" }], timestamp: 2 },
];
const tick = () => handlers.turn_start({ type: "turn_start" }, ctx);
const askContext = () => handlers.context({ type: "context", messages: baseMessages }, ctx);

// No open tasks → never inject, no matter how many idle turns pass.
for (let i = 0; i < 10; i++) tick();
assert.equal(askContext(), undefined, "no reminder when there are no open tasks");

// A fresh open task; creating it resets the since-tool idle counter.
await call("TaskCreate", { subject: "Reminder probe" });

// Below the idle-turn threshold → still no reminder (proves reset-on-tool-use).
for (let i = 0; i < 9; i++) tick();
assert.equal(askContext(), undefined, "no reminder before the idle-turn threshold");

// Crossing the threshold → exactly one reminder, appended at the tail.
tick();
const injected = askContext();
assert(injected && Array.isArray(injected.messages), "reminder injection returns a messages array");
assert.equal(injected.messages.length, baseMessages.length + 1, "reminder appends exactly one message");
assert.deepEqual(
	injected.messages.slice(0, baseMessages.length),
	baseMessages,
	"cached prefix is byte-identical — append-only, no cache burst",
);
const reminderMsg = injected.messages.at(-1);
assert.equal(reminderMsg.role, "user", "reminder is a user message at the tail");
assert.match(reminderMsg.content[0].text, /<system-reminder>/, "reminder is wrapped in a system-reminder block");
assert.match(reminderMsg.content[0].text, /Reminder probe/, "reminder echoes the open task list");
assert.deepEqual(baseMessages.length, 2, "input messages array is not mutated");

// Throttle: it does not fire again on the very next context call.
assert.equal(askContext(), undefined, "reminder is throttled for REMINDER_TURNS turns after firing");

console.log("✅ pi-task-tools smoke test passed");

async function call(name, params) {
	return handlers.tools[name].execute("call", params, undefined, undefined, ctx);
}

