const GOAL_WAIT_REGISTRY_SYMBOL = Symbol.for("valkyriweb.piGoal.waitRegistry.v1");
let monitorUiPromise: Promise<MonitorUi> | undefined;
let codingAgentUiPromise: Promise<Pick<typeof import("@valkyriweb/pi-coding-agent"), "CustomEditor">> | undefined;
const MONITORS_PANE_ID = "monitors";

function loadMonitorUi(): Promise<MonitorUi> {
	monitorUiPromise ??= import("@valkyriweb/pi-tui");
	return monitorUiPromise;
}

function loadCodingAgentUi(): Promise<Pick<typeof import("@valkyriweb/pi-coding-agent"), "CustomEditor">> {
	codingAgentUiPromise ??= import("@valkyriweb/pi-coding-agent");
	return codingAgentUiPromise;
}

function objectSchema(properties: JsonSchemaProperties, required: string[] = []): JsonSchema {
	return required.length > 0
		? { type: "object", required, properties }
		: { type: "object", properties };
}

function stringSchema(description?: string): JsonSchema {
	return description ? { type: "string", description } : { type: "string" };
}

function numberSchema(description?: string): JsonSchema {
	return description ? { type: "number", description } : { type: "number" };
}

function booleanSchema(description?: string): JsonSchema {
	return description ? { type: "boolean", description } : { type: "boolean" };
}

function stringLiteralSchema(value: string): JsonSchema {
	return { type: "string", const: value };
}

class BorderLine {
	private color: (str: string) => string;

	constructor(color: (str: string) => string) {
		this.color = color;
	}

	invalidate(): void {}

	render(width: number): string[] {
		return [this.color("-".repeat(Math.max(1, width)))];
	}
}

class InlineText {
	private text: string;

	constructor(text: string) {
		this.text = text;
	}

	invalidate(): void {}

	render(width: number): string[] {
		return [singleLineDisplay(this.text, Math.max(1, width))];

