	// ------------------- message rendering -------------------

	// Warm the pi-tui handle so the rich card is ready by the time any
	// monitor-event renders (the renderer itself is sync and can't await).
	void loadMonitorUi();

	const STATUS_GLYPH: Record<string, string> = {
		running: "●",
		exited: "✓",
		killed: "■",
		failed: "✗",
	};

	// Clean feed card mirroring the built-in memory_saved renderer: a glyph +
	// description headline, an indented output tail, and a dim meta footer. The
	// steer `content` delivered to the harness/model is untouched — only the TUI
	// feed rendering changes, so wake/notify behavior is identical. Until pi-tui
	// is loaded, fall back to a single InlineText line (keeps the lazy-load).
	pi.registerMessageRenderer("monitor-event", (msg, _opts, theme) => {
		const tui = monitorUiSync;
		if (!tui) {
			const content = singleLineDisplay(String(msg.content));
			return new InlineText(theme.fg("text", `• ${content}`));
		}
		const { Container, Text } = tui;
		const d = (msg.details ?? {}) as {
			description?: string;
			status?: string;
			event?: string;
			tail?: unknown;
			logPath?: string;
			totalLines?: number;
			wakeCount?: number;
			maxWakeups?: number;
			exitCode?: number | null;
			signal?: string | null;
			error?: string;
			reason?: string;
			suppressed?: number;
		};

		// Fall back to the raw content line for any message lacking our detail shape.
		if (!d.description && !d.status) {
			return new Text(theme.fg("accent", "▸ ") + theme.fg("dim", String(msg.content)), 0, 0);
		}

		const container = new Container();
		const glyph = STATUS_GLYPH[d.status ?? ""] ?? "▸";
		const glyphColor = d.status === "failed" ? "warning" : d.status === "running" ? "accent" : "dim";
		const exitBit =
			d.exitCode != null ? ` · exit ${d.exitCode}${d.signal ? ` (${d.signal})` : ""}` : "";
		container.addChild(
			new Text(
				theme.fg(glyphColor, glyph) +
					" " +
					theme.bold(d.description ?? "monitor") +
					theme.fg("dim", ` · ${d.status ?? d.event ?? "event"}${exitBit}`),
				0,
				0,
			),
		);

		const tail = Array.isArray(d.tail)
			? (d.tail as unknown[]).filter((l): l is string => typeof l === "string")
			: [];
		for (const line of tail.slice(-NOTIFY_TAIL_LINES)) {
			container.addChild(new Text(`  ${theme.fg("muted", line)}`, 0, 0));
		}
		if (d.error) container.addChild(new Text(`  ${theme.fg("warning", d.error)}`, 0, 0));

		const meta: string[] = [];
		if (typeof d.totalLines === "number") meta.push(`${d.totalLines} line${d.totalLines !== 1 ? "s" : ""}`);
		if (typeof d.wakeCount === "number" && typeof d.maxWakeups === "number") meta.push(`wake ${d.wakeCount}/${d.maxWakeups}`);
		if (d.suppressed) meta.push(`${d.suppressed} suppressed`);
		if (d.reason) meta.push(d.reason);
		if (d.logPath) meta.push(`log ${d.logPath}`);
		if (meta.length > 0) container.addChild(new Text(`  ${theme.fg("dim", meta.join(" · "))}`, 0, 0));

		return container;
	});
}

